files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 1rem;
}

.card {
  background: var(--card);
  padding: 2rem 1.5rem;
  border: 3px solid var(--accent);
  border-radius: 4px;
  box-shadow: 6px 6px 0 var(--accent);
  text-align: center;
  width: 100%;
  max-width: 420px;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  color: var(--accent);
  font-family: 'Courier New', monospace;
}

.count {
  display: block;
  font-size: 4rem;
  font-weight: 700;
  font-family: 'Courier New', monospace;
  margin-bottom: 1.5rem;
  padding: 0.5rem;
  background: var(--bg);
  border: 2px solid var(--muted);
  border-radius: 2px;
  min-height: 1.2em;
  line-height: 1.2;
}

.controls {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: 'Courier New', monospace;
  font-size: 1.25rem;
  font-weight: 700;
  padding: 0.75rem 1.25rem;
  min-width: 5rem;
  background: var(--accent);
  color: var(--text);
  border: 3px solid var(--text);
  border-radius: 2px;
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s;
  box-shadow: 4px 4px 0 var(--bg);
}

button:hover {
  background: #ff5c7a;
  box-shadow: 4px 4px 0 var(--muted);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

button:active {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 var(--bg);
}

.hint {
  margin-top: 1.5rem;
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.4;
}

@media (max-width: 360px) {
  .card { padding: 1.5rem 1rem; }
  .count { font-size: 3rem; }
  button { font-size: 1rem; padding: 0.6rem 1rem; min-width: 4rem; }
}

const countEl = document.getElementById('count');
let count = 0;

function updateDisplay() {
  countEl.textContent = String(count);
}

document.getElementById('increase').addEventListener('click', () => {
  count += 1;
  updateDisplay();
});

document.getElementById('decrease').addEventListener('click', () => {
  count -= 1;
  updateDisplay();
});

document.getElementById('reset').addEventListener('click', () => {
  count = 0;
  updateDisplay();
});

updateDisplay();
